const item = $input.item.json;
const rawTopic = item['Topic'] || '';
const fullId = item.id || '';
const shortId = fullId ? fullId.substring(0, 7) : 'norec';
let slug = rawTopic.toLowerCase().replace(/[^\w\s-]/g, '').replace(/\s+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
if (slug.length > 40) { slug = slug.substring(0, 40); const cut = slug.lastIndexOf('-'); if (cut > 15) slug = slug.substring(0, cut); }
slug = slug.replace(/^-|-$/g, '') || 'broll';
const genDate = $now.setZone('Asia/Manila').toFormat('yyyy-MM-dd');
const folderName = genDate + '_' + slug + '_' + shortId;
const ratio = item['Ratio'] || '';
const ratioText = ratio === 'Portrait' ? 'vertical 9:16 portrait format' : 'horizontal 16:9 landscape format';
const aspectRatio = ratio === 'Portrait' ? '9:16' : '16:9';

const sep = '==============================';
const NOTES_TAG = 'B-ROLL (Manus skill)';
const REF_TAG = 'B-ROLL CLIP INDEX (Manus skill)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = (tag) => new RegExp('\\n*' + sep + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + sep + '\\n)|$)', 'g');

const notesBase = (item['Reel_Notes'] || '').replace(blockRe(NOTES_TAG), '').trim();
const refBase = (item['BRoll_Reference'] || '').replace(blockRe(REF_TAG), '').trim();

return { json: {
  record_id: fullId,
  topic: rawTopic,
  folder_name: folderName,
  gen_date: genDate,
  short_id: shortId,
  script: item['Script'] || '',
  category: item['Category'] || 'General',
  broll_generated: item['BRoll_Generated'] || '',
  broll_reference: refBase,
  sep: sep,
  stage_tag: NOTES_TAG,
  ref_tag: REF_TAG,
  notes_base: notesBase,
  ratio: ratio,
  ratio_text: ratioText,
  aspect_ratio: aspectRatio
} };

const d = $input.item.json;
const P = [];
P.push('Segment a video script into B-roll scenes for the AlfredAI content engine.');
P.push('');
P.push('CATEGORY: ' + d.category);
P.push('TOPIC: ' + d.topic);
P.push('RATIO: ' + d.ratio);
P.push('');
P.push('SCRIPT:');
P.push(d.script);
if (d.broll_generated) {
  P.push('');
  P.push('EXISTING B-ROLL BRIEF (already written by the production brief generator for this same video). Your scene list MUST stay consistent with it. Reuse each of these ideas where it maps to a sentence in the script, keeping the same subject and intent. Only add a new scene where the brief has a genuine gap. Do not contradict it.');
  P.push(d.broll_generated);
}
if (d.broll_reference) {
  P.push('');
  P.push('EXISTING STYLE REFERENCE for this video (match the visual direction):');
  P.push(d.broll_reference);
}
P.push('');
P.push('SCOPE - IMPORTANT: You are NOT writing the final image or video prompts. A downstream Manus skill (alfred-broll-generator) owns prompt authoring, visual metaphor selection, and all brand language. It has its own scene-template and brand-asset references. Your job is only: segmentation, narrative role, timing, file naming, and a short creative direction per scene.');
P.push('');
P.push('STEP 1 - Read the full script and identify every sentence that needs B-roll footage.');
P.push('');
P.push('STEP 2 - Assign each one a narrative role, exactly one of: Hook, Problem/Pain, Gap/Complexity, Reality Check, Solution/Implication, Caveat, CTA.');
P.push('');
P.push('STEP 3 - Assign a visual style, exactly one of: Abstract, Realistic.');
P.push('- Abstract motion graphic for: Problem/Pain, Gap/Complexity, Reality Check, CTA');
P.push('- Realistic construction footage for: Hook, Solution/Implication, Caveat');
P.push('');
P.push('STEP 4 - Write scene_direction: 2 to 3 sentences describing what the viewer should see and the camera or subject motion that runs through the whole clip (for example a slow push-in on the subject, a pan across the site, or the subject carrying out an action from start to end). Every scene is its own distinct shot with its own subject or setting. Concrete and specific to this script. Do NOT write hex codes, camera jargon, style boilerplate, or a structured prompt - the skill adds all of that.');
P.push('');
P.push('STEP 5 - Generate a MINIMUM of 5 scenes, more if the script has additional strong insertion points. Order them in script order.');
P.push('');
P.push('STEP 6 - TIMESTAMPS (mandatory). Assume the voiceover is read at 150 words per minute.');
P.push('- timing_start: mm:ss offset where the insertion_point sentence begins. Compute as round(words_before_insertion_point / 150 * 60) seconds, formatted mm:ss.');
P.push('- duration_seconds: integer seconds the clip must cover, computed as round(words_in_insertion_point / 150 * 60), clamped to a minimum of 5 and a maximum of 8.');
P.push('- timing_end: mm:ss equal to timing_start plus duration_seconds.');
P.push('- Timestamps must be strictly increasing across scenes and must never overlap. If two scenes would overlap, move the later scene to the next non-overlapping sentence.');
P.push('');
P.push('STEP 7 - CHAINING. chain_from_previous is false by default. Set it to true only when the scene is one continuous shot with the previous scene: same subject, same setting, and the camera move or action carries straight on with no cut. Distinct B-roll cuts are never chained. The first scene is always false. Most scripts have no chained scenes at all.');
P.push('');
P.push('STEP 8 - CLOSING FRAME. For each scene write end_frame_note: one short sentence describing the exact final frame. It is only used to open the next scene when that next scene is chained.');
P.push('');
P.push('Output ONLY this JSON:');
P.push('{ "scenes": [ { "id": "scene_1", "insertion_point": "exact sentence from script copied verbatim", "narrative_role": "Hook", "visual_style": "Abstract", "file_slug": "3-5-word-hyphenated-keyword", "scene_direction": "2-3 sentences on what the viewer sees and the motion through the clip", "timing_start": "0:00", "timing_end": "0:06", "duration_seconds": 6, "chain_from_previous": false, "end_frame_note": "short description of the final frame" } ] }');
P.push('');
P.push('STRICT RULES:');
P.push('- insertion_point must be copied verbatim from the script');
P.push('- file_slug must be 3-5 words, lowercase, hyphenated');
P.push('- narrative_role and visual_style must use the exact values listed above');
P.push('- chain_from_previous must be a JSON boolean');
P.push('- No extra keys, no markdown, no code fences');
P.push('- Do not explain your reasoning. Output the JSON object and nothing else.');
const body = {
  model: 'claude-sonnet-5',
  max_tokens: 16000,
  thinking: { type: 'disabled' },
  system: 'You are a video production specialist for AlfredAI, a construction AI company. You segment scripts into B-roll scene lists with timing. You do not author final generation prompts. Return ONLY valid JSON - no markdown, no code fences, no explanation.',
  messages: [{ role: 'user', content: P.join('\n') }]
};
return { json: { ...d, claude_body: JSON.stringify(body) } };

const response = $input.item.json;
const sourceData = $('2. Extract Record Data').first().json;
const blocks = (response && Array.isArray(response.content)) ? response.content : [];
const textBlock = blocks.find(b => b && b.type === 'text');
let raw = textBlock ? (textBlock.text || '') : '';
const stopReason = (response && response.stop_reason) ? response.stop_reason : '';
const apiError = (response && response.error && response.error.message) ? String(response.error.message).substring(0, 200) : '';
raw = raw.replace(/```json/g, '').replace(/```/g, '').trim();
let props = {};
let parseOk = false;
let parseNote = '';
try {
  props = JSON.parse(raw);
  parseOk = !!(props.scenes && Array.isArray(props.scenes) && props.scenes.length > 0);
  if (!parseOk) { parseNote = 'JSON parsed but contained no scenes array'; }
} catch (e) {
  props = {};
  parseOk = false;
  parseNote = raw ? ('JSON parse failed: ' + String(e.message).substring(0, 120)) : 'Claude returned no text block';
}
if (!parseOk) {
  if (apiError) { parseNote = 'API error: ' + apiError; }
  else if (stopReason === 'max_tokens') { parseNote = parseNote + ' (stop_reason=max_tokens - raise max_tokens or disable thinking)'; }
  else if (stopReason) { parseNote = parseNote + ' (stop_reason=' + stopReason + ')'; }
}
// T-51: scenes are distinct cuts by default; only an explicit continuous shot is chained.
const scenes = parseOk ? props.scenes.map((s, i) => ({
  id: s.id || ('scene_' + (i + 1)),
  insertion_point: s.insertion_point || '',
  narrative_role: s.narrative_role || '',
  visual_style: s.visual_style || '',
  file_slug: s.file_slug || ('scene-' + (i + 1)),
  scene_direction: s.scene_direction || '',
  timing_start: s.timing_start || '0:00',
  timing_end: s.timing_end || '',
  duration_seconds: Math.min(8, Math.max(5, parseInt(s.duration_seconds) || 5)),
  chain_from_previous: i !== 0 && s.chain_from_previous === true,
  end_frame_note: s.end_frame_note || '',
  file_name: (s.id || ('scene_' + (i + 1))) + '_' + (s.file_slug || ('scene-' + (i + 1))) + '.mp4'
})) : [];
return { json: {
  ...sourceData,
  scenes: scenes,
  scene_count: scenes.length,
  parse_ok: parseOk && scenes.length > 0,
  parse_note: parseNote,
  stop_reason: stopReason
} };

const folderResponse = $input.item.json;
const ctx = $('4. Parse Scene Props').first().json;
const folderId = folderResponse.id || '';
const folderLink = folderId ? 'https://drive.google.com/drive/folders/' + folderId : '';
return { json: { ...ctx, folder_id: folderId, folder_link: folderLink, folder_ok: !!folderId } };

const d = $input.item.json;
const folderId = d.folder_id || '';
const folderUrl = d.folder_link || '';
const aspect = d.aspect_ratio || '16:9';
const scenePayload = d.scenes.map(s => ({
  id: s.id,
  file_name: s.file_name,
  narrative_role: s.narrative_role,
  visual_style: s.visual_style,
  scene_direction: s.scene_direction,
  duration_seconds: s.duration_seconds,
  timing_start: s.timing_start,
  timing_end: s.timing_end,
  chain_from_previous: s.chain_from_previous === true,
  end_frame_note: s.end_frame_note,
  insertion_point: s.insertion_point
}));
const chained = scenePayload.filter(s => s.chain_from_previous).map(s => s.id);
const M = [];
M.push('Render the complete B-roll clip set for one AlfredAI reel, then upload every clip to Google Drive. Follow every instruction below exactly.');
M.push('');
M.push('NON-INTERACTIVE - READ THIS FIRST: This task was dispatched automatically by n8n. There is no human in this session and no one will answer a question. Do NOT ask clarifying questions. Do NOT wait for confirmation. Do NOT present options and pause. Skip the skill clarifying-questions step entirely. Duration, aspect ratio, narrative role, and visual style are fixed per scene in the payload below. You choose the visual metaphor and mood yourself - see below. Proceed straight to generation. If something is genuinely missing, note it in your task output and continue - never stall.');
M.push('');
M.push('GENERATOR: Use the standard Manus generation tools - generate_image for keyframes and generate_video for clips. Do NOT use Higgsfield for this task. Higgsfield is out of scope for automated b-roll and its credits are reserved for manual, highly customised work.');
M.push('');
M.push('BATCH: This is a full clip set, not a single scene. Render ALL ' + d.scene_count + ' scenes below in one task. Do not stop after the first scene.');
M.push('');
M.push('ASPECT RATIO: ' + aspect + '. Every keyframe and every clip must be this aspect ratio. No letterboxing, no padding, no cropping after the fact.');
M.push('');
M.push('SCENES:');
M.push(JSON.stringify(scenePayload, null, 2));
M.push('');
M.push('YOUR JOB - PROMPT AUTHORING (this is what the skill is for):');
M.push('1. For each scene, read narrative_role and scene_direction. Select the best-fitting visual metaphor from references/scene-templates.md for that narrative_role. Choose it yourself based on scene_direction - do NOT ask which one to use, and do NOT default to the split-frame or maze metaphors unless the direction clearly calls for them.');
M.push('2. Build the full generation prompt from references/brand-assets.md using the documented 9-part video prompt structure, in the Abstract or Realistic style given by visual_style. Apply the brand palette (#0d0d1a navy, #00d9ff cyan, #ffd700 gold, #ff006e hot pink), neon bloom on abstract scenes, and the standard no-audio / no-overlay technical specs.');
M.push('3. scene_direction describes what must actually happen in the clip and is specific to this script. Honour it. The metaphor template is the visual vocabulary; scene_direction is the content.');
M.push('4. Render each scene for its duration_seconds value, not the 8 second default.');
M.push('');
M.push('KEYFRAMES AND MOTION (mandatory):');
M.push('1. Every scene is its own distinct shot unless it has chain_from_previous = true. ' + (chained.length ? 'Chained scenes in this set: ' + chained.join(', ') + '. Every other scene is unchained.' : 'No scene in this set is chained, so every scene is unchained.'));
M.push('2. For every unchained scene, call generate_image twice at aspect ratio ' + aspect + ' - a first keyframe and a last keyframe - both composed from the scene_direction of that same scene. Then call generate_video with keyframes.first and keyframes.last set and generate_audio false.');
M.push('3. The first and last keyframe of a scene show the same subject and setting, with the camera in a clearly different position or the subject in a clearly different state, so the clip moves across its whole length: push-in, pull-out, pan, orbit, tracking shot, or the subject carrying out the action in scene_direction. Never pair two unrelated images as first and last keyframe - that renders a held frame followed by a late morph.');
M.push('4. Never hold the first frame. Motion starts in the first second and continues to the last frame. A clip that stays near-static and then morphs into its end image near the end is a failed clip.');
M.push('5. Never reuse a keyframe, opening frame or closing frame from another scene as the first keyframe of an unchained scene. Every unchained scene opens on a frame that is visibly different from the opening frame of every other scene.');
M.push('6. Only for a scene with chain_from_previous = true: extract the final frame of the immediately preceding rendered clip with ffmpeg (last frame, full resolution, PNG), use it as keyframes.first, and generate the last keyframe fresh so the camera or subject keeps moving through the clip. The end_frame_note of the previous scene describes that opening frame. Render a chained scene only after the scene before it has finished.');
M.push('');
M.push('PRE-SHIP QUALITY CHECK (mandatory - run it with ffmpeg on the rendered clips BEFORE uploading anything):');
M.push('1. CLIP COUNT: exactly ' + d.scene_count + ' clips exist, one per scene, none missing, none duplicated.');
M.push('2. ASPECT RATIO: every clip is ' + aspect + '.');
M.push('3. DURATION: every clip matches its duration_seconds within 1 second.');
M.push('4. DISTINCT OPENINGS: extract the first frame of every clip and compare it with the first frame of every other clip (ffmpeg ssim filter, both frames scaled to 320 px wide). An unchained clip whose first frame matches the first frame of another clip (SSIM 0.90 or higher) fails.');
M.push('5. MOTION: extract frames at 10, 25, 40, 55 and 70 percent of the clip duration and compare each frame with the next one (same SSIM method). A clip where every consecutive pair scores SSIM 0.97 or higher has barely moved and fails.');
M.push('6. CHAINED SEAMS: every chained clip opens on the closing frame of the previous clip with no visible jump, colour shift, or subject teleport.');
M.push('7. BRAND: colours match the AlfredAI palette. Abstract scenes have neon bloom glow. No text overlays, no logos, no captions, no watermarks burned into any clip.');
M.push('8. AUDIO: every clip is silent. No generated audio, no music, no voiceover.');
M.push('9. INTEGRITY: no clip is corrupt, black, or truncated. Each plays start to finish.');
M.push('');
M.push('REGENERATE ONCE: a clip that fails any check is re-rendered one time only, with new first and last keyframes that follow the KEYFRAMES AND MOTION rules, and then checked again. If it still fails, keep the better of the two renders, upload it, and flag it in the clip index. Never re-render any clip more than once.');
M.push('');
M.push('UPLOAD (MANDATORY - required final step, do not skip it. Do not stop at a production brief):');
M.push('DESTINATION_FOLDER_ID: ' + folderId);
M.push('DESTINATION_FOLDER_URL: ' + folderUrl);
M.push('');
M.push('Export each clip as MP4 named exactly with its file_name value from the scene list above. After the quality check, upload ALL clips to the user Google Drive using rclone, targeting the EXISTING destination folder by its ID with the flag --drive-root-folder-id ' + folderId + ' so the MP4s land directly INSIDE that existing folder. The destination is a shared drive, so include shared-drive support. Run the upload EXACTLY ONCE; do not re-run or duplicate. Do NOT create a new folder. Do NOT use the folder ID as a new folder name. Do NOT rename the files. Do NOT leave the clips only in your task workspace. Do NOT upload any stills, keyframes, frame grabs, thumbnails, logs, or intermediate files to that folder - only the ' + d.scene_count + ' final MP4 clips.');
M.push('');
M.push('OUTPUT - CLIP INDEX: After uploading, list in your task output every file you placed in that folder, each with its file name, timing_start, the metaphor you selected, chained yes or no, the highest opening-frame SSIM against any other clip (check 4), and the lowest consecutive-frame SSIM from check 5. Mark every clip that still failed after its one re-render as QA FAIL with the check it failed and the measured value. A production brief is not required.');
const msg = M.join('\n');
return { json: { ...d, manus_message: msg } };

const resp = $input.item.json || {};
const ctx = $('5. Build Manus Message').first().json;
const project = 'dbagdS2KAma9gkhqK7QKJ5';
const wanted = 'alfred-broll-generator';
const source = 'workflow default';
const rec = ctx.record_id || '(no id)';
if (resp.ok === false || !Array.isArray(resp.data)) { throw new Error('skill.list failed for Manus project ' + project + ' on record ' + rec + ': ' + JSON.stringify(resp).substring(0, 300) + '. Nothing submitted.'); }
const all = resp.data.filter(Boolean);
const norm = s => String(s || '').trim().toLowerCase();
const projectSkills = all.filter(s => s.owner_type === 'project');
const matches = projectSkills.filter(s => norm(s.name) === norm(wanted));
if (matches.length !== 1 || !matches[0].id) {
  const nonProject = all.filter(s => s.owner_type !== 'project' && norm(s.name) === norm(wanted)).map(s => (s.owner_type || 'unknown') + ' ' + s.id);
  let why;
  if (matches.length > 1) why = matches.length + ' project skills share this name (' + matches.map(s => s.id).join(', ') + ')';
  else if (nonProject.length) why = 'only non-project copies exist [' + nonProject.join(', ') + ']; personal, team, official and app skills are not allowed';
  else why = 'no project skill with this name';
  throw new Error('Skill ' + wanted + ' (' + source + ') not resolved for record ' + rec + ' in Manus project ' + project + ': ' + why + '. Project skills available: ' + (projectSkills.map(s => s.name).join(', ') || '(none)') + '. Nothing submitted.');
}
const hit = matches[0];
const body = {
  message: { content: [{ type: 'text', text: ctx.manus_message }], enable_skills: [hit.id], force_skills: [hit.id] },
  title: (ctx.topic || 'B-Roll') + ' - ' + ctx.record_id,
  project_id: project,
  hide_in_task_list: false,
  agent_profile: 'manus-1.6'
};
return { json: { ...ctx, manus_project_id: project, resolved_skill_id: hit.id, resolved_skill_name: hit.name || wanted, resolved_skill_owner_type: hit.owner_type, resolved_skill_source: source, skill_resolve_error: '', manus_body: JSON.stringify(body) } };

const r = $input.item.json || {};
const ctx = $('5c. Pick Skill').first().json;
const taskId = r.task_id || (r.data && r.data.task_id) || '';
if (!taskId || r.ok === false) { throw new Error('Manus task.create failed for record ' + (ctx.record_id || '(no id)') + ' with skill ' + ctx.resolved_skill_name + ' (' + ctx.resolved_skill_owner_type + ', ' + ctx.resolved_skill_id + '): no task_id returned. Response: ' + JSON.stringify(r).substring(0, 400)); }
const taskUrl = r.task_url || (r.data && r.data.task_url) || ('https://manus.im/app/' + taskId);
const driveQ = "'" + ctx.folder_id + "' in parents and trashed = false and mimeType contains 'video/'";
return { json: {
  ...ctx,
  manus_task_id: taskId,
  manus_task_url: taskUrl,
  manus_has_task: true,
  manus_error: '',
  drive_q: driveQ,
  poll_attempt: 0
} };

const resp = $input.item.json;
const ctx = $('6a. Restore Before Poll').first().json;
const MAX_POLL_ATTEMPTS = 24;
const files = (resp && Array.isArray(resp.files)) ? resp.files : [];
const found = files.length;
const expected = ctx.scene_count || 0;
const allIn = expected > 0 && found >= expected;
const timedOut = !allIn && ctx.poll_attempt >= MAX_POLL_ATTEMPTS;
return { json: {
  ...ctx,
  clips_found: found,
  clips_expected: expected,
  clip_names: files.map(f => f.name),
  all_clips_in: allIn,
  poll_timed_out: timedOut
} };

const fresh = $input.item.json || {};
const d = $('6c. Parse Clip Count').first().json;
const f = fresh.fields || fresh;
const refetchOk = !!(fresh && fresh.id);
const freshRef = (f && typeof f.BRoll_Reference === 'string') ? f.BRoll_Reference : (d.broll_reference || '');
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';

const sep = d.sep;
const NOTES_TAG = d.stage_tag;
const REF_TAG = d.ref_tag;
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const blockRe = (tag) => new RegExp('\\n*' + sep + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + sep + '\\n)|$)', 'g');
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');

const names = d.clip_names || [];
const rows = d.scenes.map(s => {
  const landed = names.indexOf(s.file_name) !== -1;
  return '[' + s.timing_start + ' - ' + s.timing_end + '] ' + s.id + ' (' + s.duration_seconds + 's) ' + s.file_name + (landed ? '' : '  <-- MISSING') + '\n  Role: ' + s.narrative_role + ' | Style: ' + s.visual_style + ' | Chained: ' + (s.chain_from_previous ? 'yes' : 'no') + '\n  Insert on: ' + s.insertion_point;
}).join('\n');

const refBlock = sep + '\n' + REF_TAG + '\nUpdated: ' + stamp + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task URL: ' + d.manus_task_url + '\n\n' + rows;
const refBase = freshRef.replace(blockRe(REF_TAG), '').trim();
const refFinal = (refBase ? refBase + '\n\n' : '') + refBlock;

const notesBlock = sep + '\n' + NOTES_TAG + '\nUpdated: ' + stamp + '\nStage: Complete' + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task ID: ' + d.manus_task_id + '\nManus Task URL: ' + d.manus_task_url;
const notesBase = refetchOk ? freshNotes.replace(blockRe(NOTES_TAG), '').trim() : (d.notes_base || '');
const notesFinal = (notesBase ? notesBase + '\n\n' : '') + notesBlock;

// MC-1: only the run that owns the record may write its final status.
const stillOurs = !refetchOk || ((f.BRoll_URL || '') === d.folder_link && f.Status === 'B-Roll Processing');
const lateBlock = sep + '\n' + NOTES_TAG + '\nUpdated: ' + stamp + '\nStage: Late - Manus had not uploaded the clips after 120 minutes' + '\nClips: ' + d.clips_found + ' of ' + d.clips_expected + '\nDrive folder: ' + d.folder_link + '\nManus Task ID: ' + d.manus_task_id + '\nManus Task URL: ' + d.manus_task_url + '\nDetail: The Manus task may still finish. Once the clips are in the folder, set status to Ready for B-roll Generation - the workflow picks them up from this folder without a new Manus task.';
const lateNotes = (notesBase ? notesBase + '\n\n' : '') + lateBlock;

return { json: { ...d, scene_map_final: refFinal, reel_notes_final: notesFinal, late_notes_final: lateNotes, still_ours: stillOurs, is_late: d.poll_timed_out === true } };

const d = $input.item.json;
const B = 'alfredaiNoteBoundary';
const BASE_ID = 'appgBzSHGSK2v8B6g';
const TABLE_ID = 'tblSBKG2Zx2nZUPIT';
const recId = d.record_id || '';
const atUrl = recId ? ('https://airtable.com/' + BASE_ID + '/' + TABLE_ID + '/' + recId) : '';
const files = (d.scenes || []).map(s => '- ' + s.file_name + '  [' + s.timing_start + ' - ' + s.timing_end + '] ' + s.narrative_role);
const lines = [
'AlfredAI Content Engine - generated asset folder',
'',
'Brand: AlfredAI',
'Content type: B-roll clip set',
'Generated: ' + (d.gen_date || '') + ' (PHT)',
'Topic: ' + (d.topic || ''),
'Category: ' + (d.category || ''),
'Aspect ratio: ' + (d.aspect_ratio || ''),
'',
'Airtable record ID: ' + recId,
'Airtable record: ' + atUrl,
'Airtable base: ' + BASE_ID,
'',
'Expected clips: ' + (d.scene_count || 0),
...files,
'',
