  if (!p) continue;
  by[p] = by[p] || { videos: [], info_id: '' };
  if (String(f.mimeType || '').indexOf('video/') === 0) by[p].videos.push(f.name);
  else if (f.name === '00_INFO.txt') by[p].info_id = f.id;
}
let cand = null;
for (const pf of g.prior_folders) {
  const e = by[pf.id];
  if (e && e.videos.length >= 3) { cand = { id: pf.id, name: pf.name, videos: e.videos, info_id: e.info_id }; break; }
}
let block = '';
if (!g.gate_list_ok || !checkOk) block = 'Could not read the B-roll folders in Drive, so earlier Manus tasks for this record could not be counted. Nothing submitted.';
else if (g.prior_count >= g.max_per_record) block = 'Record cap reached: ' + g.prior_count + ' B-roll folders already exist for this record (max ' + g.max_per_record + ' Manus tasks per record) and none could be reused as a full clip set. Nothing submitted. Check the folders by hand.';
else if (g.today_count >= g.daily_cap) block = 'Daily cap reached: ' + g.today_count + ' B-roll tasks already created today (cap ' + g.daily_cap + ', CONTROL Daily_BRoll_Cap). Nothing submitted. Set status back to Ready for B-roll Generation tomorrow.';
return [{ json: { ...g, recover_candidate: cand, has_candidate: !!cand, info_url: cand ? ('https://www.googleapis.com/drive/v3/files/' + (cand.info_id || 'missing') + '?alt=media&supportsAllDrives=true') : '', gate_block: block, gate_ok: !block } }];

