const rows = [];
for (const line of info.split('\n')) {
  const x = line.trim().match(/^- (\S+\.mp4)\s*(?:\[(.+?) - (.+?)\])?\s*(.*)$/);
  if (!x) continue;
  const landed = c.videos.indexOf(x[1]) !== -1;
  rows.push((x[2] ? '[' + x[2] + ' - ' + x[3] + '] ' : '') + x[1] + (landed ? '' : '  <-- MISSING') + (x[4] ? '\n  Role: ' + x[4].trim() : ''));
}
const listing = rows.length ? rows.join('\n') : c.videos.slice().sort().join('\n');
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const count = found + ' of ' + (expected || found);
const refBlock = d.sep + '\n' + d.ref_tag + '\nUpdated: ' + stamp + '\nClips: ' + count + '\nDrive folder: ' + link + '\nManus Task URL: ' + taskUrl + '\nRecovered from the existing folder ' + c.name + ' - no new Manus task.\n\n' + listing;
const notesBlock = d.sep + '\n' + d.stage_tag + '\nUpdated: ' + stamp + '\nStage: Complete (recovered from existing folder, no new Manus task)\nClips: ' + count + '\nDrive folder: ' + link + '\nManus Task ID: ' + taskId + '\nManus Task URL: ' + taskUrl;
return [{ json: { ...d, recover_full: full, recover_found: found, recover_expected: expected, recover_link: link, recover_ref: (d.broll_reference ? d.broll_reference + '\n\n' : '') + refBlock, recover_notes: (d.notes_base ? d.notes_base + '\n\n' : '') + notesBlock } }];

